    '英検2級では、賛成か反対かを述べる問題が必ず出る。support（支持する）と oppose（反対する）、in favor of（賛成して）と against（反対して）。この対を押さえておけば、自分の立場をすぐ言葉にできる。',
    '法律まわりは、許す側と禁じる側で分けると整理しやすい。allow・permit が許す側、ban・forbid・prohibit が禁じる側である。どれも後ろの形が決まっているので、形ごと覚えておきたい。',
